static size_t checks,objects,cases;static const char*current;
static void req(bool p,const char*s){++checks;if(!p){std::fprintf(stderr,"FAIL %s: %s\n",current,s);std::exit(3);}}
struct Context{API&a;ggml_context*c;Context(API&api,bool no):a(api),c(a.ggml_init({8*1024*1024,nullptr,no})){}~Context(){a.ggml_free(c);}ggml_tensor*t(int64_t n0=8,int64_t n1=4,int64_t n2=2,int64_t n3=2,ggml_type ty=GGML_TYPE_F32){return a.ggml_new_tensor_4d(c,ty,n0,n1,n2,n3);}};
static void compare(Context&n,Context&g){req(n.a.ggml_used_mem(n.c)==g.a.ggml_used_mem(g.c),"arena use");std::vector<ggml_tensor*>ns,gs;for(auto*t=n.a.ggml_get_first_tensor(n.c);t;t=n.a.ggml_get_next_tensor(n.c,t))ns.push_back(t);for(auto*t=g.a.ggml_get_first_tensor(g.c);t;t=g.a.ggml_get_next_tensor(g.c,t))gs.push_back(t);req(ns.size()==gs.size(),"all intermediate nodes");std::unordered_map<ggml_tensor*,ggml_tensor*>map;map[nullptr]=nullptr;for(size_t i=0;i<ns.size();++i)map[ns[i]]=gs[i];auto nbase=(uintptr_t)n.a.ggml_get_mem_buffer(n.c),gbase=(uintptr_t)g.a.ggml_get_mem_buffer(g.c);
for(size_t i=0;i<ns.size();++i){auto*a=ns[i];auto*b=gs[i];++objects;req((uintptr_t)a-nbase==(uintptr_t)b-gbase,"tensor arena offset");req(a->type==b->type&&a->op==b->op&&a->flags==b->flags,"type/op/flags");req(std::memcmp(a->ne,b->ne,sizeof a->ne)==0&&std::memcmp(a->nb,b->nb,sizeof a->nb)==0,"shape/stride");req(std::memcmp(a->op_params,b->op_params,sizeof a->op_params)==0,"all parameter bytes");req(std::memcmp(a->name,b->name,sizeof a->name)==0,"name and tail");req(map.count(a->view_src)&&map[a->view_src]==b->view_src&&a->view_offs==b->view_offs,"view alias/offset");for(int j=0;j<GGML_MAX_SRC;++j)req(map.count(a->src[j])&&map[a->src[j]]==b->src[j],"source links incl self-reference");req(bool(a->data)==bool(b->data),"payload presence");if(a->data)req((uintptr_t)a->data-nbase==(uintptr_t)b->data-gbase,"payload arena offset");req(a->buffer==nullptr&&b->buffer==nullptr&&a->extra==nullptr&&b->extra==nullptr,"default backend metadata");}}
template<class Fn>void test(API&n,API&g,const char*label,Fn fn){current=label;for(bool no:{false,true}){Context a(n,no),b(g,no);fn(a);fn(b);compare(a,b);++cases;}}
static void suite(API&n,API&g){
test(n,g,"arithmetic",[](Context&x){auto&a=x.a;auto c=x.c;auto p=x.t(),q=x.t(8,1,1,1),s=x.t(1,1,1,1);a.ggml_dup(c,p);a.ggml_dup_inplace(c,p);a.ggml_add(c,p,q);a.ggml_add_inplace(c,p,q);a.ggml_sub(c,p,q);a.ggml_mul(c,p,q);a.ggml_div(c,p,q);a.ggml_add1(c,p,s);a.ggml_add1_inplace(c,p,s);a.ggml_sqr(c,p);a.ggml_sqrt(c,p);a.ggml_log(c,p);a.ggml_sin(c,p);a.ggml_cos(c,p);a.ggml_scale_bias(c,p,-0.0f,1.25f);a.ggml_scale_bias_inplace(c,p,0.75f,-0.0f);a.ggml_fill(c,p,-0.0f);a.ggml_fill_inplace(c,p,2.0f);for(int j=0;j<GGML_UNARY_OP_COUNT;++j){a.ggml_unary(c,p,(ggml_unary_op)j);a.ggml_unary_inplace(c,p,(ggml_unary_op)j);}});
test(n,g,"norm/GLU",[](Context&x){auto&a=x.a;auto c=x.c;auto p=x.t(),q=x.t();for(float eps:{0.0f,1e-6f,1e-5f}){a.ggml_norm(c,p,eps);a.ggml_norm_inplace(c,p,eps);a.ggml_rms_norm(c,p,eps);a.ggml_rms_norm_inplace(c,p,eps);a.ggml_rms_norm_back(c,p,q,eps);a.ggml_l2_norm(c,p,eps);a.ggml_group_norm(c,p,2,eps);a.ggml_group_norm_inplace(c,p,2,eps);}a.ggml_clamp(c,p,-0.0f,3.0f);a.ggml_clamp_inplace(c,p,-2.0f,0.0f);for(int j=0;j<GGML_GLU_OP_COUNT;++j){a.ggml_glu(c,p,(ggml_glu_op)j,false);a.ggml_glu(c,p,(ggml_glu_op)j,true);a.ggml_glu_split(c,p,q,(ggml_glu_op)j);}a.ggml_swiglu_oai(c,p,q,1.7f,7.0f);a.ggml_swiglu_clamp(c,p,q,8.0f);});
test(n,g,"expert/matrix",[](Context&x){auto&a=x.a;auto c=x.c;auto p=x.t(32,6,2,1),q=x.t(32,4,4,1);auto r=a.ggml_mul_mat(c,p,q);a.ggml_mul_mat_set_prec(r,GGML_PREC_F32);a.ggml_mul_mat_set_hint(r,(ggml_op_hint)0);req(a.ggml_prec_set_acc(r,GGML_PREC_DEFAULT),"matrix acc precision");req(a.ggml_prec_set_src(r,GGML_PREC_F32,1),"matrix source precision");req(!a.ggml_prec_set_src(r,GGML_PREC_F32,0),"unsupported source precision");auto b=x.t(32,2,3,1),ids=x.t(4,3,1,1,GGML_TYPE_I32);auto mm=a.ggml_mul_mat_id(c,p,b,ids);a.ggml_prec_set_acc(mm,GGML_PREC_F32);a.ggml_prec_set_src(mm,GGML_PREC_F32,1);auto weights=x.t(256,6,2,1,GGML_TYPE_Q4_K);(void)weights;auto z=x.t(8,4,2,1),bias=x.t(8,16,1,1),ii=x.t(4,2,1,1,GGML_TYPE_I32);a.ggml_add_id(c,z,bias,ii);auto h=x.t(8,4,1,1,GGML_TYPE_F16),hb=x.t(8,1,1,1);a.ggml_add_cast(c,h,hb,GGML_TYPE_F32);auto op=x.t(16,4,2,1),ob=x.t(8,4,4,1);a.ggml_out_prod(c,op,ob);});
test(n,g,"matrix dtype registry",[](Context&x){auto&a=x.a;auto c=x.c;for(auto ty:{GGML_TYPE_F32,GGML_TYPE_F16,GGML_TYPE_BF16,GGML_TYPE_Q4_K,GGML_TYPE_Q6_K,GGML_TYPE_Q8_0,GGML_TYPE_Q8_K}){auto w=x.t(256,6,2,1,ty),b=x.t(256,4,4,1);a.ggml_mul_mat(c,w,b);auto eb=x.t(256,2,3,1),ii=x.t(4,3,1,1,GGML_TYPE_I32);a.ggml_mul_mat_id(c,w,eb,ii);}});
test(n,g,"reduction/repeat/concat",[](Context&x){auto&a=x.a;auto c=x.c;auto p=x.t(),q=x.t();a.ggml_sum(c,p);a.ggml_sum_rows(c,p);a.ggml_mean(c,p);a.ggml_cumsum(c,p);a.ggml_count_equal(c,p,q);auto matrix=x.t(8,4,1,1);a.ggml_argmax(c,matrix);auto small=x.t(8,1,1,1);a.ggml_repeat(c,small,p);a.ggml_repeat_4d(c,small,8,4,2,2);a.ggml_repeat_back(c,p,small);for(int i=0;i<4;++i)a.ggml_concat(c,p,q,i);a.ggml_diag(c,small);a.ggml_diag_mask_inf(c,p,7);a.ggml_diag_mask_zero_inplace(c,p,0);a.ggml_tri(c,x.t(8,8,2,1),GGML_TRI_TYPE_LOWER);});
test(n,g,"rows/copy/layout",[](Context&x){auto&a=x.a;auto c=x.c;auto p=x.t(8,16,2,1),ii=x.t(4,2,1,1,GGML_TYPE_I32);a.ggml_set_name(p,"base");a.ggml_get_rows(c,p,ii);auto pi=x.t(8,16,2,1,GGML_TYPE_I32);a.ggml_get_rows(c,pi,ii);auto values=x.t(8,4,2,1),dest=x.t(8,16,2,1),idx=x.t(4,1,1,1,GGML_TYPE_I64);a.ggml_set_rows(c,dest,values,idx);auto copy=x.t(8,4,2,1);a.ggml_set_name(copy,"destination");a.ggml_cpy(c,values,copy);a.ggml_set_name(copy,"");a.ggml_cpy(c,values,copy);a.ggml_cast(c,values,GGML_TYPE_F16);a.ggml_cont(c,values);a.ggml_cont_4d(c,values,16,4,1,1);auto dst=x.t(16,8,1,1),src=x.t(4,2,1,1);a.ggml_acc(c,dst,src,dst->nb[1],dst->nb[2],dst->nb[3],4);a.ggml_acc_inplace(c,dst,src,dst->nb[1],dst->nb[2],dst->nb[3],0);a.ggml_set(c,dst,src,dst->nb[1],dst->nb[2],dst->nb[3],4);a.ggml_set_inplace(c,dst,src,dst->nb[1],dst->nb[2],dst->nb[3],0);a.ggml_argsort(c,values,GGML_SORT_ORDER_ASC);a.ggml_argsort(c,values,GGML_SORT_ORDER_DESC);a.ggml_top_k(c,values,4);a.ggml_top_k(c,values,0);});
test(n,g,"attention/RoPE",[](Context&x){auto&a=x.a;auto c=x.c;auto p=x.t(8,4,2,2),mask=x.t(8,8,1,1,GGML_TYPE_F16);auto soft=a.ggml_soft_max_ext(c,p,mask,0.5f,8.0f);a.ggml_soft_max_ext_inplace(c,p,nullptr,1.0f,-0.0f);auto sinks=x.t(2,1,1,1);a.ggml_soft_max_add_sinks(soft,sinks);a.ggml_soft_max_add_sinks(soft,nullptr);auto q=x.t(8,4,2,1),k=x.t(8,8,1,1,GGML_TYPE_F16),v=x.t(8,8,1,1,GGML_TYPE_F16);auto flash=a.ggml_flash_attn_ext(c,q,k,v,nullptr,0.25f,0.0f,0.0f);a.ggml_flash_attn_ext_set_prec(flash,GGML_PREC_F32);req(a.ggml_flash_attn_ext_get_prec(flash)==GGML_PREC_F32,"flash precision");req(a.ggml_prec_set_acc(flash,GGML_PREC_DEFAULT),"flash acc precision");a.ggml_flash_attn_ext_set_n_kv_max(flash,7);auto fs=x.t(2,1,1,1);a.ggml_flash_attn_ext_add_sinks(flash,fs);a.ggml_flash_attn_ext_add_sinks(flash,nullptr);int sections[4]={1,1,1,1};for(int mode:{0,2,8,24}){auto pos=x.t(mode&8?8:2,1,1,1,GGML_TYPE_I32),freq=x.t(4,1,1,1);a.ggml_rope_multi(c,q,pos,freq,8,sections,mode,2048,10000.0f,0.75f,1.0f,1.2f,32.0f,1.0f);a.ggml_rope_multi_inplace(c,q,pos,nullptr,8,nullptr,mode,4096,1000000.0f,1.0f,0.0f,1.0f,0.0f,0.0f);}});
test(n,g,"recurrent",[](Context&x){auto&a=x.a;auto c=x.c;auto sx=x.t(12,8,2,1),kernel=x.t(4,8,1,1);a.ggml_ssm_conv(c,sx,kernel);for(int count:{1,4})for(int gatewidth:{1,8}){auto q=x.t(8,2,3,2),k=x.t(8,2,3,2),v=x.t(8,2,3,2),gate=x.t(gatewidth,2,3,2),beta=x.t(1,2,3,2),state=x.t(8,8,2,2);a.ggml_gated_delta_net(c,q,k,v,gate,beta,state,count);}});
}
static ggml_context*abort_ctx;static size_t abort_used;static API*abort_api;
static void rejected(const char*){_exit(abort_api->ggml_used_mem(abort_ctx)==abort_used?81:82);}
static void invalid(API&api,int which){Context x(api,true);auto c=x.c;auto p=x.t(8,4,2,1),b=x.t(8,3,1,1),ids=x.t(4,2,1,1,GGML_TYPE_F32);abort_api=&api;abort_ctx=c;abort_used=api.ggml_used_mem(c);api.ggml_set_abort_callback(rejected);switch(which){case 0:api.ggml_add(c,p,b);break;case 1:api.ggml_mul_mat(c,p,b);break;case 2:api.ggml_mul_mat_id(c,p,b,ids);break;case 3:api.ggml_concat(c,p,b,4);break;case 4:api.ggml_glu_split(c,p,b,GGML_GLU_OP_SWIGLU);break;case 5:api.ggml_get_rows(c,p,ids);break;case 6:api.ggml_soft_max_ext(c,p,ids,1,0);break;case 7:api.ggml_rope_multi(c,p,ids,nullptr,8,nullptr,0,0,10000,1,0,1,0,0);break;} _exit(83);}
static void errors(API&n,API&g){current="transactional native error pairs";for(int which=0;which<8;++which)for(API*a:{&n,&g}){auto pid=fork();req(pid>=0,"fork");if(!pid)invalid(*a,which);int status=0;req(waitpid(pid,&status,0)==pid&&WIFEXITED(status)&&WEXITSTATUS(status)==81,"rejection before arena mutation");}}
int main(int argc,char**argv){if(argc!=3)return 2;API n(argv[1]),g(argv[2]);suite(n,g);errors(n,g);auto seen=symbol<uint64_t(*)()>(g.h,"fg158_builder_seen")();bool rollback=std::getenv("GGML_GOOSE_GRAPH_BUILDERS")&&std::strcmp(std::getenv("GGML_GOOSE_GRAPH_BUILDERS"),"0")==0;req(rollback?seen==0:seen==UINT64_C(0xfffffffff),"all36Goose modes or explicit rollback");auto live=symbol<int64_t(*)()>(g.h,"fg157_context_heap_live")();req(live==0,"no leaked contexts");std::printf("PASS independent graph-builders cases=%zu tensors=%zu checks=%zu native_error_pairs=8 Goose_modes=0x%llx live_context_heaps=0\n",cases,objects,checks,(unsigned long long)seen);}
